1	package app
2	
3	import (
4		"strings"
5	
6		tea "charm.land/bubbletea/v2"
7		"charm.land/lipgloss/v2"
8	
9		"github.com/anthnel/devdesk/internal/ui/components"
10		"github.com/anthnel/devdesk/internal/ui/overlay"
11		"github.com/anthnel/devdesk/internal/ui/theme"
12	)
13	
14	// View is the program's frame. The router is the only place that sets the
15	// terminal state (alternate screen now), the views only provide content.
16	func (a *App) View() tea.View {
17		v := tea.NewView(a.Render())
18		v.AltScreen = true
19		v.ReportFocus = true            // mode 1004: BlurMsg/FocusMsg (DEVDESK-210)
20		if !a.themeDetectionPending() { // an unset background keeps the terminal's own colour readable
21			v.BackgroundColor = terminalBackground(a.colorProfile, theme.ColorBackground)
22		}
23		v.ProgressBar = terminalProgress(a.progress)                 // DEVDESK-211
24		v.WindowTitle = windowTitle(a.currentView, a.currentContext) // DEVDESK-257
25		return v
26	}
27	
28	// Render renders the interface: header, title line, viewport, footer (Rule 124).
29	// An open overlay replaces the whole thing.
30	func (a *App) Render() string {
31		if overlay := a.activeOverlay(); overlay != "" {
32			return lipgloss.Place(a.width, a.height, lipgloss.Center, lipgloss.Center, overlay,
33				lipgloss.WithWhitespaceStyle(lipgloss.NewStyle().Background(theme.ColorBackground)))
34		}
35	
36		header := a.renderHeader() + "\n" + a.renderTitleLine()
37		// The footer is rendered first: whether a bar opens it decides how the
38		// viewport closes its bottom edge.
39		footer := a.renderViewFooter()
40		barBelow := !a.frameless() && components.OpensWithBarFrame(footer)
41		body := a.renderBody(barBelow)
42		inner := fitHeight(header, body, footer, a.height)
43	
44		placed := lipgloss.Place(a.width, a.height, lipgloss.Left, lipgloss.Top, inner,
45			lipgloss.WithWhitespaceStyle(lipgloss.NewStyle().Background(theme.ColorBackground)))
46		return a.withPalette(placed)
47	}
48	
49	// withPalette draws the open command palette over the final screen. The
50	// composition happens after fitHeight and Place, on exactly height lines of
51	// width cells, so the geometry is in screen rows whatever the view is.
52	func (a *App) withPalette(screen string) string {
53		lines := a.paletteLines()
54		if len(lines) == 0 {
55			return screen
56		}
57		r := a.paletteRect()
58		composed := overlay.Compose(strings.Split(screen, "\n"), lines, r.X, r.Y, a.width)
59		return strings.Join(composed, "\n")
60	}
61	
62	// fitHeight stacks header, body and footer in at most height lines.
63	// lipgloss.Place pads a short block but never crops a tall one, so on a very
64	// small terminal (header 8 + title 1 + the viewport's minimum + footer) the
65	// frame would be taller than the screen. The surplus is taken from the body
66	// first: the footer carries the messages, so it outranks viewport rows. The
67	// lines taken sit just above the body's last line, so the viewport's bottom
68	// border (or the junction a bar attaches to) survives the cut; a body cut
69	// entirely is simply gone. If header and footer alone are taller than the terminal, the
70	// stack is cut to its first height lines, the simplest floor. At normal
71	// heights nothing is cut.
72	func fitHeight(header, body, footer string, height int) string {
73		parts := []string{header}
74		if body != "" {
75			parts = append(parts, body)
76		}
77		if footer != "" {
78			parts = append(parts, footer)
79		}
80		lines := strings.Split(strings.Join(parts, "\n"), "\n")
81		excess := len(lines) - height
82		if height <= 0 || excess <= 0 {
83			return strings.Join(lines, "\n")
84		}
85	
86		headerLen := strings.Count(header, "\n") + 1
87		bodyLen := 0
88		if body != "" {
89			bodyLen = strings.Count(body, "\n") + 1
90		}
91		cut := min(excess, bodyLen)
92		if cut > 0 {
93			end := headerLen + bodyLen
94			if cut < bodyLen {
95				end-- // keep the body's last line
96			}
97			lines = append(lines[:end-cut], lines[end:]...)
98		}
99		if len(lines) > height {
100			lines = lines[:height]
101		}
102		return strings.Join(lines, "\n")
103	}
104	
105	// activeOverlay returns the overlay to draw instead of the view, or "" when
106	// there is none. The order matches the one handleKeyMsg dispatches in, so the
107	// overlay holding the keyboard is the one on screen.
108	func (a *App) activeOverlay() string {
109		switch {
110		case a.switchingTo != "":
111			return a.renderContextSwitchingOverlay()
112		case a.showHelp:
113			return a.renderHelpOverlay()
114		case a.showContextList:
115			return a.renderContextListOverlay()
116		}
117		return ""
118	}
119	
120	// renderBody fills the viewport with the active view's content, padded to the
121	// full inner width so no line shows the terminal's own background (Rule 115).
122	// barBelow is true when the footer opens with a components.BarFrame: the
123	// viewport's bottom corners then become T-junctions (Rule 136).
124	func (a *App) renderBody(barBelow bool) string {
125		content := "View not found: " + string(a.currentView)
126		if view, ok := a.views[a.currentView]; ok {
127			content = view.Render()
128		}
129	
130		innerWidth := a.viewport.Width() - 2 // -2 for the borders
131		if a.frameless() {
132			innerWidth = a.viewport.Width()
133		}
134		a.viewport.SetContent(lipgloss.NewStyle().
135			Background(theme.ColorBackground).
136			Foreground(theme.ColorText).
137			Width(innerWidth).
138			Render(content))
139	
140		body := a.viewport.View()
141	
142		if barBelow {
143			body = replaceViewportBottomCorners(body)
144		}
145		return body
146	}
147	
148	// renderTitleLine draws the viewport's top border carrying the view's title —
149	// or, for a frameless view, a titled rule with no corners: GetTitle() keeps a
150	// reader oriented where a top border would draw the top of a nonexistent box.
151	func (a *App) renderTitleLine() string {
152		title := ""
153		if view, ok := a.views[a.currentView]; ok {
154			if hv, implements := view.(HeaderView); implements {
155				title = hv.GetTitle()
156			}
157		}
158		if a.frameless() {
159			return theme.RenderTitledRule(title, a.width)
160		}
161		return theme.RenderBorderTitleTrail(title, a.frameTrail(title), a.width)
162	}
163	
164	// frameTrail asks the active view for its border trail, within the budget the
165	// theme leaves after title. It returns "" when there is no room, the view has
166	// no trail, or the trail is wider than its budget.
167	func (a *App) frameTrail(title string) string {
168		view, ok := a.views[a.currentView]
169		if !ok {
170			return ""
171		}
172		tv, ok := view.(FrameTrailView)
173		if !ok {
174			return ""
175		}
176		budget := theme.BorderTrailBudget(title, a.width)
177		if budget <= 0 {
178			return ""
179		}
180		trail := tv.FrameTrail(budget)
181		if lipgloss.Width(trail) > budget {
182			return ""
183		}
184		return trail
185	}
186	
187	// frameless reports whether the active view draws its own frames (see
188	// FramelessView). The default is framed.
189	func (a *App) frameless() bool {
190		view, ok := a.views[a.currentView]
191		if !ok {
192			return false
193		}
194		fv, implements := view.(FramelessView)
195		return implements && fv.Frameless()
196	}
197	
198	// renderViewFooter returns the active view's footer, or "" when it has none.
199	func (a *App) renderViewFooter() string {
200		if view, ok := a.views[a.currentView]; ok {
201			if fv, ok := view.(FooterView); ok {
202				return fv.RenderFooter(a.width)
203			}
204		}
205		return ""
206	}
207	
208	// replaceViewportBottomCorners turns the viewport's bottom └ and ┘ into the
209	// T-junctions ├ and ┤, so the filter bar rendered below it in the footer joins
210	// the border into one closed rectangle instead of two stacked boxes.
211	func replaceViewportBottomCorners(body string) string {
212		lastNewline := strings.LastIndex(body, "\n")
213		if lastNewline == -1 {
214			return body
215		}
216		lastLine := body[lastNewline+1:]
217		lastLine = strings.Replace(lastLine, "└", "├", 1)
218		lastLine = strings.Replace(lastLine, "┘", "┤", 1)
219		return body[:lastNewline+1] + lastLine
220	}
221

