21	// The frame, compared by cells (DEVDESK-281, task 281.2).
22	//
23	// The router assembles the frame in a few passes (renderBody's Style.Width,
24	// fitHeight, the whole-frame lipgloss.Place, the palette overlay). Changing how
25	// one of them pads changes bytes without necessarily changing what a terminal
26	// shows, so the safety net is not a byte comparison: testutil.Cells decodes the
27	// frame into (glyph, foreground, background) per cell, and
28	//
29	//   - TestFrameHasNoBareCell holds Rule 115: no cell of the frame is left on the
30	//     terminal's default background, and the frame is exactly width x height;
31	//   - TestFrameCellsGolden compares the whole decoded frame, case by case,
32	//     against internal/app/testdata/frames/<case>.cells.
33	//
34	// Both run at 120x40 with the TrueColor profile, on the default theme.
35	//
36	// Regenerate the goldens after an intended rendering change, then read the diff
37	// as cells:
38	//
39	//	go test ./internal/app -run TestFrameCellsGolden -update-frames -count=1
40	//
41	// The flag is the package's own: pass it with the package path, not ./...
42	
43	var updateFrames = flag.Bool("update-frames", false, "rewrite internal/app/testdata/frames/*.cells from the current frames")
44	
45	const (
