259	func TestFrameHasNoBareCell(t *testing.T) {
260		useDefaultTheme(t)
261		for _, c := range frameCases() {
262			t.Run(c.name, func(t *testing.T) {
263				frame := c.build(t).Render()
264	
265				// A missing cell is as bare as one on the default background.
266				rows := testutil.Cells(frame)
267				if len(rows) != framesHeight {
268					t.Errorf("frame has %d rows, want %d", len(rows), framesHeight)
269				}
270				for r, row := range rows {
271					if len(row) != framesWidth {
272						t.Errorf("row %d has %d cells, want %d", r, len(row), framesWidth)
273						break
274					}
275				}
276	
277				// BareCells sees a default background only. A reversed cell whose
278				// foreground was the terminal's default has "default-fg" as its
279				// background, and one reversed over a default background has
280				// "default-bg": neither is DefaultColor, and both leave the cell's
281				// fill to the terminal's palette. No case has one today (the
282				// palette's input cursor is reversed too, but over ColorText: its
283				// background is #rrggbb and only its foreground is "default-bg"), so
284				// none is allowed; a case that needs one lists it here with a reason.
285				if got := reversedDefaultBackgrounds(rows); len(got) > 0 {
286					t.Errorf("%d cells whose background is a reversed terminal default (default-fg or default-bg)\n%s", len(got), describeBare(got))
287				}
288	
289				bare := testutil.BareCells(frame)
290				switch {
291				case len(bare) == 0 && c.knownBare != "":
292					t.Errorf("no bare cell any more: remove knownBare (%q) from the case", c.knownBare)
293				case len(bare) > 0 && c.knownBare != "":
294					t.Logf("KNOWN GAP, not asserted: %d bare cells (%s)\n%s", len(bare), c.knownBare, describeBare(bare))
295				case len(bare) > 0:
296					t.Errorf("%d cells on the terminal's default background (Rule 115)\n%s", len(bare), describeBare(bare))
297				}
298			})
299		}
300	}
