302	// The decoder reads the sequence Lip Gloss really writes for an invalid field
303	// (Rule 140: curly underline plus an underline colour, SGR 58): the cells keep
304	// the background and the foreground the style gave them.
305	func TestCellsDecodeTheInvalidFieldUnderline(t *testing.T) {
306		useDefaultTheme(t)
307		base := lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorText)
308		out := theme.StyleInvalidField(base).Render("bad")
309		if !strings.Contains(out, "58;") {
310			t.Fatalf("premise changed: no SGR 58 in %q", out)
311		}
312		wantBG, wantFG := theme.Hex(theme.ColorBackground), theme.Hex(theme.ColorText)
313		rows := testutil.Cells(out)
314		if len(rows) != 1 || len(rows[0]) != 3 {
315			t.Fatalf("Cells(%q) = %#v, want 3 cells", out, rows)
316		}
317		for i, c := range rows[0] {
318			if c.BG != wantBG || c.FG != wantFG {
319				t.Errorf("cell %d = %+v, want fg %s bg %s", i, c, wantFG, wantBG)
320			}
321		}
322	}
