324	// reversedDefaultBackgrounds returns the position of every cell whose
325	// background is testutil.ReversedDefaultFG or testutil.ReversedDefaultBG, in
326	// reading order.
327	func reversedDefaultBackgrounds(rows [][]testutil.Cell) []testutil.Pos {
328		var out []testutil.Pos
329		for r, row := range rows {
330			for c, cell := range row {
331				if cell.BG == testutil.ReversedDefaultFG || cell.BG == testutil.ReversedDefaultBG {
332					out = append(out, testutil.Pos{Row: r, Col: c})
333				}
334			}
335		}
336		return out
337	}
