339	// describeBare summarises bare cells by row: the row, how many, and the columns
340	// of the first and last.
341	func describeBare(bare []testutil.Pos) string {
342		var b strings.Builder
343		shown := 0
344		for i := 0; i < len(bare); {
345			j := i
346			for j < len(bare) && bare[j].Row == bare[i].Row {
347				j++
348			}
349			if shown++; shown > 12 {
350				fmt.Fprintf(&b, "  ... %d more rows\n", countRows(bare[i:]))
351				break
352			}
353			fmt.Fprintf(&b, "  row %d: %d cells, columns %d to %d\n", bare[i].Row, j-i, bare[i].Col, bare[j-1].Col)
354			i = j
355		}
356		return b.String()
357	}
358	
359	func countRows(bare []testutil.Pos) int {
360		n := 0
361		for i, p := range bare {
362			if i == 0 || p.Row != bare[i-1].Row {
363				n++
364			}
365		}
366		return n
367	}
